import{_ as e,o as i,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"定期記帳","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/12-scheduled-accounting-guide.md","filePath":"v1/ja/guide/12-scheduled-accounting-guide.md"}'),r={name:"v1/ja/guide/12-scheduled-accounting-guide.md"};function o(d,a,h,n,u,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="定期記帳" tabindex="-1">定期記帳 <a class="header-anchor" href="#定期記帳" aria-label="Permalink to &quot;定期記帳&quot;">​</a></h1><h2 id="_1-この機能について" tabindex="-1">1. この機能について <a class="header-anchor" href="#_1-この機能について" aria-label="Permalink to &quot;1. この機能について&quot;">​</a></h2><p>「定期記帳」は、家賃・光熱費・サブスク・給与など、定期的に発生する収支をルールとして登録し、ルールに従って明細を自動生成する機能です。毎回の手入力を減らせます。</p><h2 id="_2-こんなときに便利" tabindex="-1">2. こんなときに便利 <a class="header-anchor" href="#_2-こんなときに便利" aria-label="Permalink to &quot;2. こんなときに便利&quot;">​</a></h2><ul><li>毎月の家賃、住宅ローン、クレジットカード返済</li><li>毎週の通勤交通費、固定の手当</li><li>毎月のサブスクリプション（動画サービス、クラウドストレージ等）</li><li>毎月の固定収入（給与、補助金等）</li></ul><h2 id="_3-使い方" tabindex="-1">3. 使い方 <a class="header-anchor" href="#_3-使い方" aria-label="Permalink to &quot;3. 使い方&quot;">​</a></h2><ol><li>「設定」から「定期記帳」を開く</li><li>新しいルールを作成し、次を入力する： <ul><li>種別：支出 / 収入</li><li>カテゴリ（収支項目）</li><li>金額</li><li>口座</li><li>タグ、メモ（任意）</li><li>実行周期：毎日 / 毎週 / 毎月（ルールに応じて日付や曜日を選択）</li><li>開始/終了：開始日は必須。終了日は任意（期限到来で自動停止）</li></ul></li><li>保存すると、ルールが定期記帳の一覧に表示される</li><li>実行タイミングになると、ルールに従って明細が生成される</li></ol><h2 id="_4-ルールと注意点" tabindex="-1">4. ルールと注意点 <a class="header-anchor" href="#_4-ルールと注意点" aria-label="Permalink to &quot;4. ルールと注意点&quot;">​</a></h2><ul><li>定期記帳で生成された明細は通常の手入力明細と同じ扱いで、一覧表示され、集計にも含まれます。</li><li>長期間アプリを開かない場合、端末によっては「完全に指定時刻どおり」に生成できないことがあります。その場合でも、次回アプリ起動時に未生成分を補完して作成します（記録漏れ防止）。</li><li>家賃改定や口座変更などがあった場合に備え、ルールは定期的に見直してください。</li><li>ルールを一時停止/終了すると以後は生成されません。再開すると次の周期から実行されます。</li></ul><h2 id="_5-よくある質問" tabindex="-1">5. よくある質問 <a class="header-anchor" href="#_5-よくある質問" aria-label="Permalink to &quot;5. よくある質問&quot;">​</a></h2><h3 id="q1-定期記帳で生成された明細が間違っていたら" tabindex="-1">Q1：定期記帳で生成された明細が間違っていたら？ <a class="header-anchor" href="#q1-定期記帳で生成された明細が間違っていたら" aria-label="Permalink to &quot;Q1：定期記帳で生成された明細が間違っていたら？&quot;">​</a></h3><p>通常の明細と同様に編集/削除できます。頻繁に起きる場合は、ルール側（金額/周期/口座など）を調整してください。</p><h3 id="q2-ルールを変更すると、過去に生成された明細も自動で変わりますか" tabindex="-1">Q2：ルールを変更すると、過去に生成された明細も自動で変わりますか？ <a class="header-anchor" href="#q2-ルールを変更すると、過去に生成された明細も自動で変わりますか" aria-label="Permalink to &quot;Q2：ルールを変更すると、過去に生成された明細も自動で変わりますか？&quot;">​</a></h3><p>変わりません。変更は今後生成される明細にのみ反映され、過去の明細は追跡のためにそのまま残ります。</p><h3 id="q3-同じ日に複数の明細が生成されますか" tabindex="-1">Q3：同じ日に複数の明細が生成されますか？ <a class="header-anchor" href="#q3-同じ日に複数の明細が生成されますか" aria-label="Permalink to &quot;Q3：同じ日に複数の明細が生成されますか？&quot;">​</a></h3><p>複数のルールを設定している場合、それぞれのルール分が生成されます。同一ルールについては、重複生成をできるだけ避けるようにしています。</p>',16)])])}const q=e(r,[["render",o]]);export{_ as __pageData,q as default};
